blocks.body:
{
    "level": "B1",
    "intro": "У цій темі ти детально вивчиш <strong>Present Continuous Passive<\/strong> (Теперішній тривалий пасив): як утворювати цю форму, коли використовувати та в чому відмінність від Present Simple Passive.",
    "rules": [
        {
            "label": "Формула",
            "color": "emerald",
            "text": "<strong>Subject + am\/is\/are + being + V3<\/strong>:",
            "example": "The house is being painted right now."
        },
        {
            "label": "Заперечення",
            "color": "rose",
            "text": "<strong>Subject + am\/is\/are + not + being + V3<\/strong>:",
            "example": "The report is not being written now."
        },
        {
            "label": "Питання",
            "color": "blue",
            "text": "<strong>Am\/Is\/Are + Subject + being + V3?<\/strong>:",
            "example": "Is the project being developed?"
        }
    ]
}

{
    "title": "1. Структура Present Continuous Passive",
    "intro": "Форма дієслова <strong>be<\/strong> залежить від підмета, а <strong>being<\/strong> залишається незмінним:",
    "items": [
        {
            "label": "I",
            "title": "am being + V3",
            "subtitle": "I am being interviewed now. — Мене зараз інтерв'юють."
        },
        {
            "label": "He\/She\/It",
            "title": "is being + V3",
            "subtitle": "The car is being repaired. — Машину ремонтують."
        },
        {
            "label": "You\/We\/They",
            "title": "are being + V3",
            "subtitle": "The documents are being checked. — Документи перевіряються."
        },
        {
            "label": "Ключ",
            "title": "being — незмінна частина",
            "subtitle": "being завжди стоїть перед V3."
        }
    ]
}

{
    "title": "2. Стверджувальні речення",
    "sections": [
        {
            "label": "Структура",
            "color": "emerald",
            "description": "Порядок слів: <strong>Subject + am\/is\/are + being + V3 (+ by agent)<\/strong>",
            "examples": [
                {
                    "en": "The house is being painted at the moment.",
                    "ua": "Будинок зараз фарбується."
                },
                {
                    "en": "The documents are being prepared right now.",
                    "ua": "Документи готуються прямо зараз."
                },
                {
                    "en": "I am being trained for the new position.",
                    "ua": "Мене навчають для нової посади."
                },
                {
                    "en": "The road is being repaired this week.",
                    "ua": "Дорогу ремонтують цього тижня."
                }
            ]
        },
        {
            "label": "Тимчасові процеси",
            "color": "sky",
            "description": "Для дій, що <strong>тривають певний період часу<\/strong>:",
            "examples": [
                {
                    "en": "A new system is being installed this month.",
                    "ua": "Нова система встановлюється цього місяця."
                },
                {
                    "en": "The building is being renovated.",
                    "ua": "Будівля ремонтується (зараз, тимчасово)."
                },
                {
                    "en": "New software is being tested at the moment.",
                    "ua": "Нове програмне забезпечення зараз тестується."
                }
            ]
        }
    ]
}

{
    "title": "3. Коли використовувати Present Continuous Passive?",
    "sections": [
        {
            "label": "Дії прямо зараз",
            "color": "emerald",
            "description": "Для дій, що <strong>відбуваються в момент мовлення<\/strong>:",
            "examples": [
                {
                    "en": "The dinner is being cooked right now.",
                    "ua": "Вечеря готується прямо зараз."
                },
                {
                    "en": "The meeting is being held at the moment.",
                    "ua": "Зустріч проводиться в даний момент."
                },
                {
                    "en": "Your order is being processed.",
                    "ua": "Ваше замовлення обробляється."
                }
            ]
        },
        {
            "label": "Тимчасові ситуації",
            "color": "blue",
            "description": "Для дій, що <strong>тривають певний період<\/strong>, але не постійно:",
            "examples": [
                {
                    "en": "The bridge is being constructed this year.",
                    "ua": "Міст будується цього року."
                },
                {
                    "en": "New employees are being trained this month.",
                    "ua": "Нові працівники навчаються цього місяця."
                },
                {
                    "en": "The project is being developed at present.",
                    "ua": "Проєкт зараз розробляється."
                }
            ]
        },
        {
            "label": "Зміни та тенденції",
            "color": "amber",
            "description": "Для опису <strong>поточних змін<\/strong>:",
            "examples": [
                {
                    "en": "More and more trees are being planted.",
                    "ua": "Все більше дерев висаджується."
                },
                {
                    "en": "The old system is being replaced gradually.",
                    "ua": "Стара система поступово замінюється."
                },
                {
                    "en": "Electric cars are being promoted heavily.",
                    "ua": "Електромобілі активно просуваються."
                }
            ]
        }
    ]
}

{
    "title": "4. Заперечні речення",
    "sections": [
        {
            "label": "Структура",
            "color": "rose",
            "description": "Додаємо <strong>not<\/strong> після am\/is\/are: <strong>Subject + am\/is\/are + not + being + V3<\/strong>",
            "examples": [
                {
                    "en": "The report is not being written at the moment.",
                    "ua": "Звіт зараз не пишеться."
                },
                {
                    "en": "The rooms are not being cleaned today.",
                    "ua": "Кімнати сьогодні не прибираються."
                },
                {
                    "en": "I am not being considered for the job.",
                    "ua": "Мене не розглядають на цю посаду."
                },
                {
                    "en": "The problem is not being addressed.",
                    "ua": "Проблема не вирішується."
                }
            ]
        },
        {
            "label": "Скорочені форми",
            "color": "amber",
            "description": "У розмовній мові: <strong>isn't being \/ aren't being<\/strong>",
            "examples": [
                {
                    "en": "The car isn't being repaired today.",
                    "ua": "Машина сьогодні не ремонтується."
                },
                {
                    "en": "The packages aren't being delivered now.",
                    "ua": "Посилки зараз не доставляються."
                },
                {
                    "en": "The issue isn't being investigated.",
                    "ua": "Питання не розслідується."
                }
            ]
        }
    ]
}

{
    "title": "5. Питальні речення",
    "sections": [
        {
            "label": "Yes\/No питання",
            "color": "blue",
            "description": "<strong>Am\/Is\/Are<\/strong> виходить на перше місце: <strong>Am\/Is\/Are + Subject + being + V3?<\/strong>",
            "examples": [
                {
                    "en": "Is the house being painted?",
                    "ua": "Будинок фарбується?"
                },
                {
                    "en": "Are the documents being checked?",
                    "ua": "Документи перевіряються?"
                },
                {
                    "en": "Am I being tested?",
                    "ua": "Мене тестують?"
                },
                {
                    "en": "Is the project being developed?",
                    "ua": "Проєкт розробляється?"
                }
            ]
        },
        {
            "label": "Wh-питання",
            "color": "sky",
            "description": "<strong>Wh-word + am\/is\/are + Subject + being + V3?<\/strong>",
            "examples": [
                {
                    "en": "What is being built there?",
                    "ua": "Що там будується?"
                },
                {
                    "en": "Why is the road being closed?",
                    "ua": "Чому дорога перекривається?"
                },
                {
                    "en": "Where are the tests being conducted?",
                    "ua": "Де проводяться тести?"
                },
                {
                    "en": "How is the problem being solved?",
                    "ua": "Як вирішується проблема?"
                }
            ]
        },
        {
            "label": "Короткі відповіді",
            "color": "amber",
            "description": "Відповіді з <strong>Yes\/No + pronoun + am\/is\/are (not)<\/strong>:",
            "examples": [
                {
                    "en": "Is the car being repaired? — Yes, it is. \/ No, it isn't.",
                    "ua": "Машина ремонтується? — Так. \/ Ні."
                },
                {
                    "en": "Are they being interviewed? — Yes, they are. \/ No, they aren't.",
                    "ua": "Їх інтерв'юють? — Так. \/ Ні."
                }
            ]
        }
    ]
}

{
    "title": "6. Порівняння Active vs Passive у Present Continuous",
    "intro": "Як перетворити активне речення на пасивне:",
    "rows": [
        {
            "en": "Active: They are painting the house now.",
            "ua": "Вони зараз фарбують будинок.",
            "note": "→ Passive: The house is being painted now."
        },
        {
            "en": "Active: The manager is checking the documents.",
            "ua": "Менеджер перевіряє документи.",
            "note": "→ Passive: The documents are being checked."
        },
        {
            "en": "Active: Workers are repairing the road.",
            "ua": "Робітники ремонтують дорогу.",
            "note": "→ Passive: The road is being repaired."
        },
        {
            "en": "Active: Someone is interviewing me.",
            "ua": "Хтось мене інтерв'юває.",
            "note": "→ Passive: I am being interviewed."
        }
    ],
    "warning": "📌 Маркери часу (now, at the moment, currently) залишаються!"
}

{
    "title": "7. Present Simple Passive vs Present Continuous Passive",
    "intro": "Порівняння двох форм — регулярні дії vs дії прямо зараз:",
    "rows": [
        {
            "en": "The house is cleaned every week.",
            "ua": "Будинок прибирається щотижня.",
            "note": "vs: The house is being cleaned now. — Будинок прибирається зараз."
        },
        {
            "en": "Cars are made in Germany.",
            "ua": "Машини виробляються в Німеччині.",
            "note": "vs: A car is being made for me. — Машина зараз виготовляється для мене."
        },
        {
            "en": "The report is prepared monthly.",
            "ua": "Звіт готується щомісяця.",
            "note": "vs: The report is being prepared now. — Звіт зараз готується."
        }
    ],
    "warning": "📌 Present Simple = регулярно, завжди. Present Continuous = зараз, у цей момент."
}

{
    "title": "8. Маркери часу для Present Continuous Passive",
    "intro": "Типові слова та вирази, що вказують на Present Continuous:",
    "items": [
        {
            "label": "Зараз",
            "title": "now, right now, at the moment, currently",
            "subtitle": "The report is being written right now."
        },
        {
            "label": "Сьогодні",
            "title": "today, this morning, this afternoon",
            "subtitle": "The meeting is being held this afternoon."
        },
        {
            "label": "Цей період",
            "title": "this week, this month, this year",
            "subtitle": "A new bridge is being built this year."
        },
        {
            "label": "Тимчасово",
            "title": "at present, for the time being, temporarily",
            "subtitle": "The office is being renovated at present."
        }
    ]
}

{
    "title": "9. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Пропуск being.",
            "wrong": "The house is painted now.",
            "right": "✅ The house is being painted now."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Неправильний порядок слів.",
            "wrong": "The report being is written.",
            "right": "✅ The report is being written."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Використання been замість being.",
            "wrong": "The car is been repaired now.",
            "right": "✅ The car is being repaired now."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Плутанина Present Simple та Continuous.",
            "wrong": "The house is being cleaned every day.",
            "right": "✅ The house is cleaned every day. (регулярно)"
        }
    ]
}

{
    "title": "Passive in Tenses",
    "items": [
        {
            "label": "Present Simple Passive — Теперішній простий пасив",
            "current": false
        },
        {
            "label": "Present Continuous Passive — Теперішній тривалий пасив",
            "current": true
        },
        {
            "label": "Present Perfect Passive — Теперішній доконаний пасив",
            "current": false
        },
        {
            "label": "Past Simple Passive — Минулий простий пасив",
            "current": false
        },
        {
            "label": "Past Continuous Passive — Минулий тривалий пасив",
            "current": false
        },
        {
            "label": "Past Perfect Passive — Минулий доконаний пасив",
            "current": false
        },
        {
            "label": "Future Simple Passive — Майбутній простий пасив",
            "current": false
        },
        {
            "label": "Future Continuous Passive — Майбутній тривалий пасив",
            "current": false
        },
        {
            "label": "Future Perfect Passive — Майбутній доконаний пасив",
            "current": false
        }
    ]
}

{
    "level": "B1",
    "intro": "У цій темі ти детально вивчиш <strong>Past Continuous Passive<\/strong> (Минулий тривалий пасив): як утворювати цю форму, коли використовувати та в чому відмінність від Past Simple Passive.",
    "rules": [
        {
            "label": "Формула",
            "color": "emerald",
            "text": "<strong>Subject + was\/were + being + V3<\/strong>:",
            "example": "The house was being painted when I arrived."
        },
        {
            "label": "Заперечення",
            "color": "rose",
            "text": "<strong>Subject + was\/were + not + being + V3<\/strong>:",
            "example": "The report was not being written at that time."
        },
        {
            "label": "Питання",
            "color": "blue",
            "text": "<strong>Was\/Were + Subject + being + V3?<\/strong>:",
            "example": "Was the project being developed?"
        }
    ]
}

{
    "title": "1. Структура Past Continuous Passive",
    "intro": "Форма дієслова <strong>be<\/strong> залежить від підмета, а <strong>being<\/strong> залишається незмінним:",
    "items": [
        {
            "label": "I\/He\/She\/It",
            "title": "was being + V3",
            "subtitle": "The car was being repaired. — Машину ремонтували."
        },
        {
            "label": "You\/We\/They",
            "title": "were being + V3",
            "subtitle": "The documents were being checked. — Документи перевіряли."
        },
        {
            "label": "Singular",
            "title": "was being + V3",
            "subtitle": "The house was being built. — Будинок будували."
        },
        {
            "label": "Ключ",
            "title": "being — незмінна частина",
            "subtitle": "being завжди стоїть перед V3."
        }
    ]
}

{
    "title": "2. Стверджувальні речення",
    "sections": [
        {
            "label": "Структура",
            "color": "emerald",
            "description": "Порядок слів: <strong>Subject + was\/were + being + V3 (+ by agent)<\/strong>",
            "examples": [
                {
                    "en": "The house was being painted when I arrived.",
                    "ua": "Будинок фарбували, коли я прийшов."
                },
                {
                    "en": "The documents were being prepared all morning.",
                    "ua": "Документи готували весь ранок."
                },
                {
                    "en": "The car was being repaired at 5 PM.",
                    "ua": "Машину ремонтували о 17:00."
                },
                {
                    "en": "The rooms were being cleaned by the staff.",
                    "ua": "Кімнати прибирав персонал."
                }
            ]
        },
        {
            "label": "Тривала дія в момент минулого",
            "color": "sky",
            "description": "Для дій, що <strong>тривали в певний момент<\/strong>:",
            "examples": [
                {
                    "en": "At 3 PM, the meeting was being held.",
                    "ua": "О 15:00 проводилася зустріч."
                },
                {
                    "en": "The road was being repaired all day.",
                    "ua": "Дорогу ремонтували весь день."
                },
                {
                    "en": "The project was being discussed when he called.",
                    "ua": "Проєкт обговорювали, коли він подзвонив."
                }
            ]
        }
    ]
}

{
    "title": "3. Коли використовувати Past Continuous Passive?",
    "sections": [
        {
            "label": "Дія в момент минулого",
            "color": "emerald",
            "description": "Для дій, що <strong>тривали в певний момент у минулому<\/strong>:",
            "examples": [
                {
                    "en": "At 8 AM, breakfast was being served.",
                    "ua": "О 8 ранку подавали сніданок."
                },
                {
                    "en": "The building was being renovated last summer.",
                    "ua": "Будівлю ремонтували минулого літа."
                },
                {
                    "en": "The reports were being prepared yesterday evening.",
                    "ua": "Звіти готували вчора ввечері."
                }
            ]
        },
        {
            "label": "Паралельні дії",
            "color": "blue",
            "description": "Коли одна дія <strong>перервала іншу тривалу<\/strong>:",
            "examples": [
                {
                    "en": "The car was being washed when it started to rain.",
                    "ua": "Машину мили, коли почався дощ."
                },
                {
                    "en": "The dinner was being cooked when the guests arrived.",
                    "ua": "Вечерю готували, коли приїхали гості."
                },
                {
                    "en": "The document was being printed when the power went out.",
                    "ua": "Документ друкували, коли вимкнули світло."
                }
            ]
        },
        {
            "label": "Тривалість процесу",
            "color": "amber",
            "description": "Для підкреслення <strong>тривалості процесу<\/strong>:",
            "examples": [
                {
                    "en": "The house was being built for two years.",
                    "ua": "Будинок будували два роки."
                },
                {
                    "en": "The project was being developed throughout the year.",
                    "ua": "Проєкт розробляли протягом року."
                },
                {
                    "en": "The investigation was being conducted all week.",
                    "ua": "Розслідування проводили весь тиждень."
                }
            ]
        }
    ]
}

{
    "title": "4. Заперечні речення",
    "sections": [
        {
            "label": "Структура",
            "color": "rose",
            "description": "Додаємо <strong>not<\/strong> після was\/were: <strong>Subject + was\/were + not + being + V3<\/strong>",
            "examples": [
                {
                    "en": "The report was not being written at that time.",
                    "ua": "Звіт не писали в той час."
                },
                {
                    "en": "The rooms were not being cleaned yesterday.",
                    "ua": "Кімнати не прибирали вчора."
                },
                {
                    "en": "The problem was not being addressed.",
                    "ua": "Проблему не вирішували."
                },
                {
                    "en": "The orders were not being processed.",
                    "ua": "Замовлення не обробляли."
                }
            ]
        },
        {
            "label": "Скорочені форми",
            "color": "amber",
            "description": "У розмовній мові: <strong>wasn't being \/ weren't being<\/strong>",
            "examples": [
                {
                    "en": "The car wasn't being repaired yesterday.",
                    "ua": "Машину вчора не ремонтували."
                },
                {
                    "en": "The packages weren't being delivered.",
                    "ua": "Посилки не доставляли."
                },
                {
                    "en": "The issue wasn't being investigated.",
                    "ua": "Питання не розслідували."
                }
            ]
        }
    ]
}

{
    "title": "5. Питальні речення",
    "sections": [
        {
            "label": "Yes\/No питання",
            "color": "blue",
            "description": "<strong>Was\/Were<\/strong> виходить на перше місце: <strong>Was\/Were + Subject + being + V3?<\/strong>",
            "examples": [
                {
                    "en": "Was the house being painted?",
                    "ua": "Будинок фарбували?"
                },
                {
                    "en": "Were the documents being checked?",
                    "ua": "Документи перевіряли?"
                },
                {
                    "en": "Was the project being developed?",
                    "ua": "Проєкт розробляли?"
                },
                {
                    "en": "Were they being interviewed?",
                    "ua": "Їх інтерв'юювали?"
                }
            ]
        },
        {
            "label": "Wh-питання",
            "color": "sky",
            "description": "<strong>Wh-word + was\/were + Subject + being + V3?<\/strong>",
            "examples": [
                {
                    "en": "What was being built there?",
                    "ua": "Що там будували?"
                },
                {
                    "en": "Why was the road being closed?",
                    "ua": "Чому дорогу перекривали?"
                },
                {
                    "en": "Where were the tests being conducted?",
                    "ua": "Де проводили тести?"
                },
                {
                    "en": "How was the problem being solved?",
                    "ua": "Як вирішували проблему?"
                }
            ]
        },
        {
            "label": "Короткі відповіді",
            "color": "amber",
            "description": "Відповіді з <strong>Yes\/No + pronoun + was\/were (not)<\/strong>:",
            "examples": [
                {
                    "en": "Was the car being repaired? — Yes, it was. \/ No, it wasn't.",
                    "ua": "Машину ремонтували? — Так. \/ Ні."
                },
